  "/site.js":{type:"application/javascript; charset=utf-8",content:"document.getElementById(\"year\")?.append(new Date().getFullYear());\nconst toggle=document.getElementById(\"navToggle\");\nconst menu=document.getElementById(\"mobileNav\");\nif(toggle&&menu){toggle.addEventListener(\"click\",()=>{const opened=menu.hidden;menu.hidden=!opened;toggle.setAttribute(\"aria-expanded\",String(opened));});menu.querySelectorAll(\"a\").forEach(a=>a.addEventListener(\"click\",()=>{menu.hidden=true;toggle.setAttribute(\"aria-expanded\",\"false\");}));}\nconst search=document.getElementById(\"transactionSearch\");\nconst rows=[...document.querySelectorAll(\"#transactions tr\")];\nsearch?.addEventListener(\"input\",()=>{const term=search.value.trim().toLowerCase();rows.forEach(tr=>{tr.hidden=!tr.textContent.toLowerCase().includes(term);});});\n"},
  "/portal.html":{type:"text/html; charset=utf-8",content:"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Dashboard Preview — BrewPOS</title><meta name=\"robots\" content=\"noindex\"><link rel=\"stylesheet\" href=\"/styles.css\"></head><body class=\"portal-body\">\n<div class=\"demo-alert\">PREVIEW ONLY — Illustrative example data. Not connected to Supabase, staff accounts, or actual customer transactions.</div>\n<div class=\"portal-layout\"><aside class=\"portal-sidebar\"><a href=\"/\" class=\"brand light-brand\"><span class=\"brand-mark\">✦</span><span>BrewPOS</span></a><small class=\"sidebar-label\">YOUR WORKSPACE</small><nav aria-label=\"Preview pages\"><a class=\"active\" href=\"#overview\">▦ &nbsp; Overview</a><a href=\"#activity\">▤ &nbsp; Transactions</a><a href=\"#health\">☁ &nbsp; Cloud status</a><a href=\"/\">↗ &nbsp; Main website</a></nav><div class=\"portal-bottom\"><b>AZURATE SOFTWARE</b><span>Merchant preview • v2.0</span></div></aside><main class=\"portal-main\"><div class=\"portal-top\"><div><span class=\"kicker\">MERCHANT PORTAL / DEMO</span><h1>Your café, at a glance.</h1><p>Take a look at what's planned for BrewPOS Hybrid.</p></div><div class=\"portal-profile\"><span class=\"profile-circle\">AC</span><span>Sample Café <small>Demo account</small></span></div></div><section id=\"overview\" class=\"portal-overview\"><div class=\"portal-cards\">\n<article><small>Total revenue (sample)</small><strong>₱24,580</strong><span class=\"up\">↗ Illustrative only</span></article>\n<article><small>Orders (sample)</small><strong>182</strong><span class=\"up\">Average ₱135/order</span></article>\n<article><small>Active barista queue</small><strong>6</strong><span>Example status</span></article>\n<article><small>Available branches</small><strong>1</strong><span>Demo branch</span></article>\n</div><div class=\"portal-section-grid\"><div class=\"portal-box chart-box\"><div class=\"box-top\"><div><h2>Revenue trend</h2><small>Example weekly revenue</small></div><span>Last 7 days</span></div><svg class=\"revenue-chart\" role=\"img\" aria-label=\"Illustrative weekly revenue trend chart\" viewBox=\"0 0 700 250\"><defs><linearGradient id=\"area\" x1=\"0\" x2=\"0\" y1=\"0\" y2=\"1\"><stop stop-color=\"#C9A88C\" stop-opacity=\".35\"/><stop offset=\"1\" stop-color=\"#C9A88C\" stop-opacity=\"0\"/></linearGradient></defs><path d=\"M10 211 L10 170 L120 155 L230 178 L340 105 L450 132 L560 70 L690 34 L690 211 Z\" fill=\"url(#area)\"/><path d=\"M10 170 L120 155 L230 178 L340 105 L450 132 L560 70 L690 34\" fill=\"none\" stroke=\"#8B5E40\" stroke-width=\"4\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/><path d=\"M10 210H690\" stroke=\"#E9E4DD\"/><g fill=\"#9F9488\" font-size=\"12\"><text x=\"10\" y=\"233\">Mon</text><text x=\"122\" y=\"233\">Tue</text><text x=\"232\" y=\"233\">Wed</text><text x=\"342\" y=\"233\">Thu</text><text x=\"452\" y=\"233\">Fri</text><text x=\"562\" y=\"233\">Sat</text><text x=\"668\" y=\"233\">Sun</text></g></svg></div>\n<div class=\"portal-box\"><div class=\"box-top\"><div><h2>Best sellers</h2><small>Example products</small></div></div><div class=\"bestseller\"><span>☕</span><div><b>Spanish Latte</b><small>68 sold</small></div><strong>38%</strong></div><div class=\"bestseller\"><span>🍵</span><div><b>Matcha Latte</b><small>41 sold</small></div><strong>24%</strong></div><div class=\"bestseller\"><span>🥐</span><div><b>Croissant</b><small>28 sold</small></div><strong>16%</strong></div></div></div></section>\n<section id=\"activity\" class=\"portal-box activity\"><div class=\"box-top\"><div><h2>Recent transactions</h2><small>All entries below are synthetic demo data</small></div><input id=\"transactionSearch\" type=\"search\" placeholder=\"Search sample orders...\" aria-label=\"Search sample orders\"></div><div class=\"table-wrap\"><table><thead><tr><th>Order</th><th>Time</th><th>Payment</th><th>Total</th><th>Status</th></tr></thead><tbody id=\"transactions\"><tr><td>BP-000182</td><td>11:45 AM</td><td>Cash</td><td>₱320</td><td><span class=\"state paid\">Completed</span></td></tr><tr><td>BP-000181</td><td>11:32 AM</td><td>GCash</td><td>₱165</td><td><span class=\"state paid\">Completed</span></td></tr><tr><td>BP-000180</td><td>11:24 AM</td><td>Cash</td><td>₱250</td><td><span class=\"state paid\">Completed</span></td></tr><tr><td>BP-000179</td><td>11:02 AM</td><td>Card</td><td>₱145</td><td><span class=\"state paid\">Completed</span></td></tr></tbody></table></div></section>\n<section id=\"health\" class=\"portal-box health\"><div><h2>Hybrid cloud readiness</h2><p>Offline outbox, idempotent sync, authentication and remote monitoring are planned, not yet connected.</p></div><span class=\"state planning\">IN DEVELOPMENT</span></section><footer class=\"portal-footer\">BrewPOS v2.0 foundation • Demo only • Not an authenticated portal</footer></main></div><script src=\"/site.js\" defer></script></body></html>"}
